// Run with Bun: bun generate.ts /absolute/path/to/reviewed-worktree
// Fixtures are generated by the reviewed TypeScript engine, not the Go port.
import { resolve } from 'path';
const source = process.argv[2];
if (!source) throw new Error('Pass the reviewed TypeScript worktree path');
const { TerrainGraph } = await import(resolve(source, 'apps/api/src/terrain/engine.ts'));
const base = {id:'fixture',name:'Fixture',sourceItemId:'test',sourceTitle:'test',dtmUrl:'',hillshadeUrl:'',center:{lat:0,lon:0},widthMeters:1000,heightMeters:1000,cellSizeMeters:100,minElevationM:0,maxElevationM:100,nodataValue:-99999};
function grid(rows:number,cols:number,elevationsM:number[]) {return {meta:{...base,rows,cols,bbox:[0,0,(cols-1)*.001,(rows-1)*.001]},elevationsM};}
function weather(pressure:number[],temperature=pressure.map(()=>250)) {return {lmstHour:12,minAirTempC:-150,minPressurePa:600,thermalWeight:0,cellTempK:temperature,cellPressurePa:pressure};}
const cases:unknown[]=[];
function add(name:string,dataset:ReturnType<typeof grid>,start:number[],end:number[],maxSlope:number,filter?:ReturnType<typeof weather>) {
 const graph=new TerrainGraph(dataset),a=graph.coordForCell(...start),b=graph.coordForCell(...end);
 const applied=filter?{...filter,cellTempK:Float32Array.from(filter.cellTempK),cellPressurePa:Float32Array.from(filter.cellPressurePa)}:undefined;
 cases.push({allowEquivalentPaths:name==='rectangular shortest',name,dataset,a,b,maxSlope,weather:filter,expected:graph.planRoutes(a,b,maxSlope,applied)});
}
add('rectangular shortest',grid(4,6,Array(24).fill(0)),[0,0],[3,5],0);
add('slope corner bottleneck',grid(2,2,[0,100,100,0]),[0,0],[1,1],10);
add('nodata corner',grid(2,2,[0,-99999,-99999,0]),[0,0],[1,1],89);
add('pressure corner bottleneck',grid(2,2,[0,0,0,0]),[0,0],[1,1],10,weather([900,500,500,900]));
add('coupled weather bottlenecks',grid(3,3,[0,0,0,0,-99999,0,0,0,0]),[1,0],[1,2],10,{...weather([400,400,400,900,900,900,800,800,800],[250,250,250,260,260,260,220,220,220]),minAirTempC:-33.15});
add('ascent and descent',grid(1,3,[0,10,0]),[0,0],[0,2],20,weather([900,850,800]));
const ridge=grid(11,11,Array(121).fill(0));ridge.meta.bbox=[77.5,18.4,77.5178,18.4169];for(let r=0;r<11;r++)ridge.elevationsM[r*11+5]=45;ridge.elevationsM[9*11+5]=5;
add('ridge strategies',ridge,[2,1],[2,9],30);
add('alternate corridor',grid(31,31,Array(961).fill(0)),[15,0],[15,30],0);
const thermal=grid(15,15,Array(225).fill(0));thermal.meta.bbox=[77.2,18.4,77.7,18.9];const p=Array(225).fill(900),t=Array(225).fill(260);for(let r=0;r<=10;r++)for(let c=4;c<=10;c++){p[r*15+c]=600;t[r*15+c]=220;}
add('thermal strategy',thermal,[2,1],[2,13],20,{...weather(p,t),minPressurePa:100,thermalWeight:.85});
await Bun.write(new URL('small-grids.json',import.meta.url),JSON.stringify(cases,null,2)+'\n');
const dataset=await Bun.file(resolve(source,'data/site-terrain.json')).json();const graph=new TerrainGraph(dataset);const a=graph.coordForCell(100,100),b=graph.coordForCell(900,900);
const queries=[30,.5,4.5].map(maxSlope=>{
 const expected=graph.planRoutes(a,b,maxSlope);
 const routePointHashes=expected.routes.map((route:{points:unknown[]})=>new Bun.CryptoHasher('sha256').update(JSON.stringify(route.points)).digest('hex'));
 expected.routes=expected.routes.map((route:{points:unknown[]})=>({...route,points:[]}));
 return {maxSlope,expected,routePointHashes};
});
await Bun.write(new URL('real-terrain.json',import.meta.url),JSON.stringify({rows:dataset.meta.rows,cols:dataset.meta.cols,a,b,queries},null,2)+'\n');
